import { existsSync } from "node:fs"
import { join } from "node:path"
import type { Metadata } from "next"
import { site } from "@/content/site"

export const ogImage = {
  url: site.ogImage,
  width: 1200,
  height: 630,
  alt: `${site.fullName}: ${site.tagline}`,
}

interface PageSeo {
  path: string
  title?: string
  description: string
  type?: "website" | "article"
  publishedTime?: string
  modifiedTime?: string
  image?: { url: string; alt: string }
}

/** Per-piece social card generated by scripts/og/make-images.py; falls back to the site card. */
export function writingImage(slug: string, title: string) {
  const url = `/og/${slug}.png`
  return existsSync(join(process.cwd(), "public", url)) ? { url, alt: title } : { url: ogImage.url, alt: ogImage.alt }
}

/**
 * Canonical URL, Markdown alternate, Open Graph and X card for one page.
 * Child pages replace (not merge) the layout's openGraph/twitter objects, so every page sets them in full.
 */
export function pageMetadata({ path, title, description, type = "website", publishedTime, modifiedTime, image }: PageSeo): Metadata {
  const fullTitle = title ? `${title} | ${site.name}` : `${site.displayName} | ${site.tagline}`
  const card = image ? { ...ogImage, ...image } : ogImage
  const mdPath = path === "/" ? "/index.md" : `${path}.md`
  return {
    ...(title ? { title } : {}),
    description,
    alternates: { canonical: path, types: { "text/markdown": mdPath } },
    openGraph: {
      type,
      url: path,
      siteName: site.name,
      locale: "en_US",
      title: fullTitle,
      description,
      images: [card],
      ...(type === "article" ? { publishedTime, modifiedTime, authors: [site.fullName] } : {}),
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [card.url] },
  }
}
